mutants.replacement:
promise &&
        // If the data was synchronously available, there is no need to set up
        // a retryer and thus no reason to call fetch
        !syncData &&
        !existingQueryIsPending ||
        !existingQueryIsFetching

promise &&
        // If the data was synchronously available, there is no need to set up
        // a retryer and thus no reason to call fetch
        !syncData ||
        !existingQueryIsPending

promise ||
        // If the data was synchronously available, there is no need to set up
        // a retryer and thus no reason to call fetch
        !syncData

context.options.persister(
            fetchFn as any,
            {
              client: context.client,
              queryKey: context.queryKey,
              meta: context.options.meta,
              signal: context.signal,
            },
            query,
          )

newResult.every((result, index) => {
            const prev = this.#result[index]
            return !prev || !shallowEqualObjects(result, prev)
          })

this.#observers.every((observer, index) => {
        return (
          observer.options.suspense && this.#result[index]?.data === undefined
        )
      })
